// Fetches new/updated events for every active calendar integration and
// flattens them into a single item list. Runs the Google Calendar API call
// here (via the credential attached to this node) rather than the native
// Google Calendar node, so we can attach owner_user_id/integration context
// onto each event ourselves instead of relying on implicit item-pairing
// through a native node's fan-out.
// Defensive: normalizes calendar_id even if it was stored as a raw
// embed URL (e.g. from an older/unimported version of the add-calendar
// endpoint) instead of the already-extracted address — same src=
// extraction logic as Calendar Integrations.json's parser.
function extractCalendarId(raw) {
  try {
    const url = new URL(raw);
    const src = url.searchParams.get('src');
    if (src) return src;
  } catch {
    // Not a URL — already a plain calendar ID/email.
  }
  return raw;
}

const items = $input.all();
const results = [];
const successfulIntegrationIds = new Set();

for (const item of items) {
  const integration = item.json;
  const calendarId = extractCalendarId(integration.calendar_id);
  const updatedMin = integration.last_synced_at || new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();

  const url = `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(calendarId)}/events`
    + `?updatedMin=${encodeURIComponent(updatedMin)}&singleEvents=true&orderBy=updated&maxResults=50`;

  let response;
  try {
    response = await this.helpers.httpRequestWithAuthentication.call(this, 'googleCalendarOAuth2Api', {
      method: 'GET',
      url,
      json: true,
    });
  } catch (err) {
    // One calendar failing (revoked access, bad ID) shouldn't block the
    // others — and we deliberately don't mark it synced below, so the next
    // run retries the same window instead of silently skipping it.
    continue;
  }

  successfulIntegrationIds.add(integration.id);

  const events = (response && response.items) || [];
  for (const ev of events) {
    if (!ev.id || ev.status === 'cancelled') continue;

    const start = ev.start && (ev.start.dateTime || ev.start.date);
    const end = ev.end && (ev.end.dateTime || ev.end.date);
    if (!start) continue;

    // Prefer the first attendee who isn't the organizer/a resource — that's
    // the lead who booked the slot, not the rep's own calendar entry.
    const attendees = ev.attendees || [];
    const lead = attendees.find((a) => !a.organizer && !a.resource) || attendees[0];
    const attendeeEmail = (lead && lead.email) || '';
    if (!attendeeEmail) continue;

    const attendeeName = (lead && lead.displayName) || attendeeEmail.split('@')[0];
    const nameParts = attendeeName.trim().split(/\s+/);
    const firstName = nameParts[0] || 'Unknown';
    const lastName = nameParts.slice(1).join(' ') || '-';

    results.push({
      json: {
        type: 'event',
        googleEventId: ev.id,
        subject: ev.summary || 'Booked Meeting',
        dueAt: start,
        endAt: end || null,
        ownerUserId: integration.owner_user_id,
        attendeeEmail,
        firstName,
        lastName,
      },
    });
  }
}

for (const id of successfulIntegrationIds) {
  results.push({ json: { type: 'synced_integration', integrationId: id } });
}

return results;
